-- Runs only in the isolated schema/reference clone.
do $$
declare ctx jsonb; company uuid; c public.ciclo; o public.orden_servicio; other public.orden_servicio; f public.orden_servicio_archivo; first_file public.orden_servicio_archivo; second_file public.orden_servicio_archivo; admin uuid:=gen_random_uuid(); before_count bigint;
begin
 select value into ctx from public.order_test_context;
 perform set_config('request.jwt.claim.sub',ctx->>'actor',true);
 insert into auth.users(id) values(admin);insert into public.app_users(id) values(admin);insert into public.app_user_roles(user_id,role_code) values(admin,'ADMIN_SISTEMA');
 company:=(public.guardar_empresa_patrocinadora('{"ruc":"20711111111","razon_social":"OS PDF TEST"}')).id;
 select * into c from public.ciclo where id=(ctx->>'cycle')::uuid;
 c:=public.guardar_ciclo(jsonb_build_object('id',c.id,'expected_updated_at',c.updated_at,'carrera_id',c.carrera_id,'fecha_inicio',c.fecha_inicio,'fecha_fin',c.fecha_fin,'nombre_promocion',c.nombre_promocion,'departamento_id',c.departamento_id,'provincia_id',c.provincia_id,'distrito_id',c.distrito_id,'capitania_id',c.capitania_id,'empresa_patrocinadora_id',company));
 o:=public.registrar_orden_servicio(jsonb_build_object('empresa_patrocinadora_id',company,'ciclo_id',c.id,'expected_ciclo_updated_at',c.updated_at,'serie','PDF','correlativo','1','fecha','2026-01-01','monto','20'));
 other:=public.registrar_orden_servicio(jsonb_build_object('empresa_patrocinadora_id',company,'ciclo_id',c.id,'expected_ciclo_updated_at',c.updated_at,'serie','PDF','correlativo','2','fecha','2026-01-01','monto','20'));
 if exists(select 1 from public.orden_servicio_archivo where orden_servicio_id=o.id) then raise exception 'OS cannot be created without a PDF';end if;
 begin perform public.preparar_archivo_os(admin,o.id,o.updated_at);raise exception 'Admin allowed';exception when insufficient_privilege then null;end;
 f:=public.preparar_archivo_os((ctx->>'coordinator')::uuid,o.id,o.updated_at);
 if f.numero_version<>1 or f.object_key<>o.id::text||'/'||f.id::text||'.pdf' then raise exception 'Server key/version invalid';end if;
 begin perform public.preparar_archivo_os((ctx->>'actor')::uuid,o.id,o.updated_at);raise exception 'Duplicate reservation accepted';exception when sqlstate 'PT409' then if sqlerrm<>'DOCUMENT_RESERVATION_EXISTS' then raise;end if;end;
 begin perform public.confirmar_archivo_os((ctx->>'actor')::uuid,o.id,f.id,100,repeat('a',64));raise exception 'Wrong initiator accepted';exception when insufficient_privilege then null;end;
 begin perform public.confirmar_archivo_os((ctx->>'coordinator')::uuid,other.id,f.id,100,repeat('a',64));raise exception 'Wrong OS confirm accepted';exception when insufficient_privilege then null;end;
 begin perform public.confirmar_archivo_os((ctx->>'coordinator')::uuid,o.id,f.id,5242881,repeat('a',64));raise exception 'Oversize accepted';exception when invalid_parameter_value then null;end;
 first_file:=public.confirmar_archivo_os((ctx->>'coordinator')::uuid,o.id,f.id,100,repeat('a',64));
 select count(*) into before_count from public.auditoria;
 perform public.confirmar_archivo_os((ctx->>'coordinator')::uuid,o.id,f.id,100,repeat('a',64));
 if (select count(*) from public.auditoria)<>before_count then raise exception 'Replay duplicated audit';end if;
 begin perform public.confirmar_archivo_os((ctx->>'coordinator')::uuid,o.id,f.id,101,repeat('a',64));raise exception 'Inconsistent confirm accepted';exception when sqlstate 'PT409' then null;end;
 begin perform public.abortar_archivo_os((ctx->>'coordinator')::uuid,o.id,f.id);raise exception 'Confirmed abort accepted';exception when sqlstate 'PT409' then null;end;
 begin update public.orden_servicio_archivo set sha256=repeat('b',64) where id=f.id;raise exception 'History edited';exception when check_violation then null;end;
 begin delete from public.orden_servicio_archivo where id=f.id;raise exception 'History deleted';exception when check_violation then null;end;
 f:=public.preparar_archivo_os((ctx->>'actor')::uuid,o.id,o.updated_at);
 if f.numero_version<>2 or f.base_archivo_id<>first_file.id then raise exception 'Replacement base invalid';end if;
 perform public.abortar_archivo_os((ctx->>'actor')::uuid,o.id,f.id);
 if (select id from public.orden_servicio_archivo where orden_servicio_id=o.id and estado_tecnico='CONFIRMADO' order by numero_version desc limit 1)<>first_file.id then raise exception 'Failure lost previous document';end if;
 second_file:=public.preparar_archivo_os((ctx->>'actor')::uuid,o.id,o.updated_at);
 second_file:=public.confirmar_archivo_os((ctx->>'actor')::uuid,o.id,second_file.id,200,repeat('b',64));
 if second_file.numero_version<>3 or second_file.base_archivo_id<>first_file.id then raise exception 'Confirmed history chain lost';end if;
 perform public.consultar_archivo_os((ctx->>'actor')::uuid,o.id,first_file.id,true);
 begin perform public.consultar_archivo_os((ctx->>'actor')::uuid,other.id,first_file.id);raise exception 'Cross OS download allowed';exception when insufficient_privilege then null;end;
 begin perform public.consultar_archivo_os(admin,o.id,first_file.id);raise exception 'Admin download allowed';exception when insufficient_privilege then null;end;
 f:=public.preparar_archivo_os((ctx->>'actor')::uuid,o.id,o.updated_at);
 perform public.anular_orden_servicio(o.id,o.updated_at,'Prueba de historia');
 begin perform public.confirmar_archivo_os((ctx->>'actor')::uuid,o.id,f.id,200,repeat('b',64));raise exception 'Annulment race accepted';exception when sqlstate 'PT409' then null;end;
 perform public.abortar_archivo_os((ctx->>'actor')::uuid,o.id,f.id);
 begin perform public.preparar_archivo_os((ctx->>'actor')::uuid,o.id,o.updated_at);raise exception 'Annulled upload accepted';exception when sqlstate 'PT409' then null;end;
 perform public.consultar_archivo_os((ctx->>'coordinator')::uuid,o.id,first_file.id,true);
 if (select count(*) from public.orden_servicio_archivo where orden_servicio_id=o.id and estado_tecnico='CONFIRMADO')<>2 then raise exception 'Historical versions lost';end if;
 if has_function_privilege('authenticated','public.preparar_archivo_os(uuid,uuid,timestamptz)','execute') or has_function_privilege('anon','public.consultar_archivo_os(uuid,uuid,uuid,boolean)','execute') then raise exception 'Service-only RPC exposed';end if;
 if has_column_privilege('authenticated','public.orden_servicio_archivo','object_key','select') or has_table_privilege('service_role','public.orden_servicio_archivo','update') then raise exception 'Unsafe raw file privileges';end if;
 update public.order_test_context set value=value||jsonb_build_object('os',o.id,'other_os',other.id,'first_file',first_file.id,'second_file',second_file.id,'admin',admin);
end $$;
-- Actual RLS/column grants, not just owner reads.
begin;
select set_config('request.jwt.claim.sub',(select value->>'actor' from public.order_test_context),true);
set local role authenticated;
do $$ begin if (select count(id) from public.orden_servicio_archivo)<>2 then raise exception 'Authorized metadata RLS failed';end if;end $$;
rollback;
begin;
select set_config('request.jwt.claim.sub',(select value->>'admin' from public.order_test_context),true);
set local role authenticated;
do $$ begin if (select count(id) from public.orden_servicio_archivo)<>0 then raise exception 'Admin metadata visible';end if;end $$;
rollback;
